	/**
	 * Default Constructor
	 */
    public HealthSystemService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new HealthSystemEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(HealthSystemRepository.class) );
		this.validator		= applicationContext.getBean(HealthSystemValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		HealthSystem
	 */
		public HealthSystem createHealthSystem( CreateHealthSystemCommand command ) {

		HealthSystem entity = new HealthSystem();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setHealthSystemId( command.getHealthSystemId() );
            entity.setName( command.getName() );
            entity.setLegalName( command.getLegalName() );
            entity.setHeadquartersCountry( command.getHeadquartersCountry() );
            entity.setWebsite( command.getWebsite() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of HealthSystem {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateHealthSystemCommand
	 * @return		HealthSystem
	 */
	public HealthSystem updateHealthSystem( UpdateHealthSystemCommand command ) {

		HealthSystem entity = new HealthSystem();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setHealthSystemId( command.getHealthSystemId() );
            entity.setName( command.getName() );
            entity.setLegalName( command.getLegalName() );
            entity.setHeadquartersCountry( command.getHeadquartersCountry() );
            entity.setWebsite( command.getWebsite() );
            entity.setFacilities( command.getFacilities() );
            entity.setSuppliers( command.getSuppliers() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of HealthSystem {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteHealthSystemCommand
	 */
	public void delete( DeleteHealthSystemCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getHealthSystemId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of HealthSystem {0} ", id );

	}

	/**
	 * Method to retrieve the HealthSystem via HealthSystemFetchOneSummary
	 * @param 	summary HealthSystemFetchOneSummary
	 * @return 	HealthSystemFetchOneResponse
	 */
	public HealthSystem getHealthSystem( HealthSystemFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "HealthSystemFetchOneSummary arg cannot be null" );

		HealthSystem entity = null;
		UUID id = summary.getHealthSystemId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a HealthSystem using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all HealthSystems
	 *
	 * @return 	List<HealthSystem>
	 */
    public List<HealthSystem> getAllHealthSystem() {
		List<HealthSystem> list = projector.findAll( new FindAllHealthSystemQuery() );
		return list;
	}


	/**
	 * add Facility to Facilities
	 * @param		command AssignFacilitiesToHealthSystemCommand
	 */
	public void addToFacilities( AssignFacilitiesToHealthSystemCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToFacilities(command.getHealthSystemId(), command.getAddTo());
	}

	/**
	 * remove Facility from Facilities
	 * @param		command RemoveFacilitiesFromHealthSystemCommand
	 */
	public void removeFromFacilities( RemoveFacilitiesFromHealthSystemCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromFacilities(command.getHealthSystemId(), command.getRemoveFrom());
	}

	/**
	 * add MedicalSupplier to Suppliers
	 * @param		command AssignSuppliersToHealthSystemCommand
	 */
	public void addToSuppliers( AssignSuppliersToHealthSystemCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToSuppliers(command.getHealthSystemId(), command.getAddTo());
	}

	/**
	 * remove MedicalSupplier from Suppliers
	 * @param		command RemoveSuppliersFromHealthSystemCommand
	 */
	public void removeFromSuppliers( RemoveSuppliersFromHealthSystemCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromSuppliers(command.getHealthSystemId(), command.getRemoveFrom());
	}




